const player=(athlete_id,position,name=`Atleta ${athlete_id}`)=>({athlete_id,name,nickname:name,position,photo:null,real_club_id:1});
export function createOwnershipFixture(teamIds){return teamIds.map((team_id,i)=>{const starters=[player(100,'GOL','Goleiro Unânime'),player(i<7?101:1100+i,'LAT',i<7?'Lateral Sete':`Lateral ${i}`),player(1200+i,'LAT'),player(1300+i,'ZAG'),player(1400+i,'ZAG'),player(102,'MEI','Meia Compartilhado'),player(1500+i,'MEI'),player(1600+i,'MEI'),player(1700+i,'ATA'),player(1800+i,'ATA'),player(1900+i,'ATA')],captain_id=i<4?102:1700+i;return{schema_version:1,season:2026,cartola_round:24,team_id,cartola_team_id:team_id,captured_at:'2026-08-20T22:00:00Z',formation:'4-3-3',starters,coach:player(800,'TEC','Técnico Popular'),captain_id,luxury_reserve:i<3?player(900,'LAT','Reserva Popular'):player(2000+i,'ATA'),budget:100,source:'fixture_locked'};});}
